    }

    op_RET() { this._ticks(3); this.regWZ = this.regPC = this.popWord(); }

    op_RET_cc(cc) {
        this._ticks(2);
        if (((this.r8[6] >>> COND_MAP[cc >> 1]) & 1) === (cc & 1)) {
