#include <stdio.h>
#include <proto/exec.h>
#include <proto/dos.h>
#include <proto/utility.h>
#include <devices/scsidisk.h>
#include "toolbox.h"

#define SENSE_LEN 252
#define MAX_DATA_LEN 4096

struct MsgPort *scsiPort;
struct IOStdReq *io_ptr;
struct SCSICmd *scsi_cmd;
UBYTE *scsi_sense;
UBYTE *scsi_data;

int scsi_isCD;
int scsi_isBlueSCSI;
int scsi_isZuluSCSI;
int scsi_isRemovable;
UBYTE scsi_apiVersion;
UBYTE scsi_capabilities;

struct FileEntry *files = NULL;
int filecount = 0;

int Toolbox_InitDevice(void);
int Toolbox_GetCapabilities(void);
static int Toolbox_InquiryHasName(const char *name);

static unsigned long long Toolbox_ParseEntrySize(const UBYTE *entry)
{
   return ((unsigned long long)entry[35] << 32)
      | ((unsigned long long)entry[36] << 24)
      | ((unsigned long long)entry[37] << 16)
      | ((unsigned long long)entry[38] << 8)
      | (unsigned long long)entry[39];
}

/* Setup the SCSI device */
int scsi_setup(char *scsi_dev, int scsi_unit)
{
   if ((scsiPort = CreateMsgPort()) == NULL)
   {
      return -1;
   }
   if ((io_ptr = (struct IOStdReq *)CreateIORequest(scsiPort, sizeof(struct IOStdReq))) == NULL)
   {
      return -1;
   }
   if (OpenDevice(scsi_dev, scsi_unit, (struct IORequest *)io_ptr, 0) != 0)
   {
      MessageBox("scsi_setup", "Error opening SCSI device");
      return -1;
   }
   if ((scsi_cmd = (struct SCSICmd *)AllocMem(sizeof(struct SCSICmd), MEMF_CLEAR)) == NULL)
   {
      return -1;
   }
   if ((scsi_sense = (UBYTE *)AllocMem(SENSE_LEN, MEMF_CLEAR)) == NULL)
   {
      return -1;
   }
   if ((scsi_data = (UBYTE *)AllocMem(MAX_DATA_LEN, MEMF_CLEAR)) == NULL)
   {
      return -1;
   }

   // Init the device and check some flags
   if (Toolbox_InitDevice() < 0)
   {
      MessageBox("scsi_setup", "Error sending inquiry to device\n");
      return -1;
   }

   if (Toolbox_GetCapabilities() != 0 && !scsi_isBlueSCSI && !scsi_isZuluSCSI)
   {
      MessageBox("scsi_setup", "Toolbox API not available on this device\n");
      return -1;
   }

   return 0;
}

void scsi_cleanup()
{
   if (files) FreeMem(files, sizeof(struct FileEntry) * (filecount + 1));
   if (scsi_data) FreeMem(scsi_data, MAX_DATA_LEN);
   if (scsi_sense) FreeMem(scsi_sense, SENSE_LEN);
   if (scsi_cmd) FreeMem(scsi_cmd, sizeof(struct SCSICmd));

   if (io_ptr) 
   {
      CloseDevice((struct IORequest *)io_ptr);
      DeleteIORequest(io_ptr);
   }
   if (scsiPort) DeleteMsgPort(scsiPort);
}

/* Send a SCSI command */
int DoScsiCmd(UBYTE *data, int datasize, UBYTE *cmd, int cmdsize, UBYTE flags)
{
   io_ptr->io_Length = sizeof(struct SCSICmd);
   io_ptr->io_Data = scsi_cmd;
   io_ptr->io_Command = HD_SCSICMD;
   scsi_cmd->scsi_Data = (UWORD *)data;
   scsi_cmd->scsi_Length = datasize;
   scsi_cmd->scsi_SenseActual = 0;
   scsi_cmd->scsi_SenseLength = SENSE_LEN;
   scsi_cmd->scsi_SenseData = scsi_sense;
   scsi_cmd->scsi_Command = cmd;
   scsi_cmd->scsi_CmdLength = cmdsize;
   scsi_cmd->scsi_Flags = flags;
   DoIO((struct IORequest *)io_ptr);
   return (io_ptr->io_Error);
}

/* Send a SCSI inquiry command to the device to gather some info */
int Toolbox_InitDevice(void)
{
   int err = 0;
#ifdef TESTMODE
   scsi_isCD = 1;
   scsi_isBlueSCSI = 1;
   scsi_isZuluSCSI = 0;
   scsi_isRemovable = 1;
#else
   UBYTE command[] = {SCSI_CMD_INQ, 0, 0, 0, 252, 0};

   if ((err = DoScsiCmd((UBYTE *)scsi_data, MAX_DATA_LEN,
                        (UBYTE *)&command, sizeof(command),
                        (SCSIF_READ | SCSIF_AUTOSENSE))) != 0)
   {
      return -1;
   }

   if (scsi_cmd->scsi_Actual)
   {
      scsi_isCD = (scsi_data[0] & 0x1F) == 0x05;
      scsi_isRemovable = (scsi_data[1] & 0x80) ? 1 : 0;
      scsi_isBlueSCSI = Strnicmp("BlueSCSI", &scsi_data[8], 8) == 0;
      scsi_isZuluSCSI = Strnicmp("ZuluSCSI", &scsi_data[8], 8) == 0;
      if (!scsi_isBlueSCSI && !scsi_isZuluSCSI)
      {
         scsi_isBlueSCSI = Toolbox_InquiryHasName("BlueSCSI");
         scsi_isZuluSCSI = Toolbox_InquiryHasName("ZuluSCSI");
      }
   }
#endif
   return err;
}

static int Toolbox_InquiryHasName(const char *name)
{
   int i;

   if (scsi_cmd->scsi_Actual < 36 + 8)
   {
      return 0;
   }

   for (i = 36; i <= (int)scsi_cmd->scsi_Actual - 8; i++)
   {
      if (Strnicmp((STRPTR)name, (STRPTR)&scsi_data[i], 8) == 0)
      {
         return 1;
      }
   }

   return 0;
}

/* Query firmware API version and capability flags */
int Toolbox_GetCapabilities(void)
{
   UBYTE command[] = {BLUESCSI_TOOLBOX_METADATA, BLUESCSI_TOOLBOX_SUBCMD_GET_CAPABILITIES, 0, 0, 0, 0, 0, 0, 8, 0};
   int err;

   scsi_apiVersion = 0;
   scsi_capabilities = 0;

   if ((err = DoScsiCmd((UBYTE *)scsi_data, MAX_DATA_LEN,
                        (UBYTE *)&command, sizeof(command),
                        (SCSIF_READ | SCSIF_AUTOSENSE))) != 0)
   {
      return -1;
   }

   if (scsi_cmd->scsi_Actual >= 2)
   {
      scsi_apiVersion = scsi_data[0];
      scsi_capabilities = scsi_data[1];
   }
   return 0;
}

/* Execute BLUESCSI_TOOLBOX_COUNT_CDS / BLUESCSI_TOOLBOX_COUNT_FILES */
int Toolbox_Count_Files(int cdrom)
{
   UBYTE command[] = {BLUESCSI_TOOLBOX_COUNT_FILES, 0, 0, 0, 0, 0, 0, 0, 0, 0};
   int err;
   int count = 0;
   if (cdrom)
   {
      command[0] = BLUESCSI_TOOLBOX_COUNT_CDS;
   }

   if ((err = DoScsiCmd((UBYTE *)scsi_data, MAX_DATA_LEN,
                        (UBYTE *)&command, sizeof(command),
                        (SCSIF_READ | SCSIF_AUTOSENSE))) != 0)
   {
      MessageBox("Toolbox_Count_Files", "SCSI error\n");
      return -1;
   }

   if (scsi_cmd->scsi_Actual)
   {
      count = (int)scsi_data[0];
   }
   return count;
}

#ifdef TESTMODE
STRPTR TestData[] = 
{
   "MacOS8_0.iso",
   "Debian.iso",
   "Mac OS 7.6.1.iso",
   "AmigaOS3.1.iso",
   "AmigaOS3.2.iso",
   "Star Wars - Dark Forces (1994)(LucasArts)[!][CDD6287].iso",
   "NetBSD-9.3-amiga.iso"
};
#endif

/* Execute BLUESCSI_TOOLBOX_LIST_CDS and create the files array */
struct FileEntry *Toolbox_List_Files(int cdrom)
{
#ifdef TESTMODE
   filecount = sizeof(TestData) / sizeof(char*);
   files = (struct FileEntry *)AllocMem(sizeof(struct FileEntry) * (filecount + 1), MEMF_CLEAR);
   
   struct FileEntry *file = files;
   for (int f = 0; f < filecount; f++)
   {
      file->Index = f;
      file->Type = BLUESCSI_FILE;
      file->Size = 4096*20000;
      sprintf(file->Number, "%d", f+1);
      Strncpy(file->Name, TestData[f], 32);
      file++;
   }
   file->Type = -1;  // EOF
#else
   
   if (cdrom)
   {
      if (!scsi_isRemovable)
      {
         MessageBox("Toolbox_List_Files", "Not a removable device!\n");
         return NULL;
      }
   }

   // Get the file count
   filecount = Toolbox_Count_Files(cdrom);
   if (filecount > 0)
   {
      struct FileEntry *file;
      UBYTE command[] = {BLUESCSI_TOOLBOX_LIST_FILES, 0, 0, 0, 0, 0, 0, 0, 0, 0};
      int err;
      file = files = (struct FileEntry *)AllocMem(sizeof(struct FileEntry) * (filecount + 1), MEMF_CLEAR);
      if (cdrom)
      {
         command[0] = BLUESCSI_TOOLBOX_LIST_CDS;
      }

      if ((err = DoScsiCmd((UBYTE *)scsi_data, MAX_DATA_LEN,
                           (UBYTE *)&command, sizeof(command),
                           (SCSIF_READ | SCSIF_AUTOSENSE))) != 0)
      {
         MessageBox("Toolbox_Count_Files", "SCSI error\n");
         return NULL;
      }

      if (scsi_cmd->scsi_Actual)
      {
         int f;
         for (f = 0; f < filecount; f++)
         {
            UBYTE *c = &scsi_data[ENTRY_SIZE * f];
            file->Index = c[0];
            file->Type = c[1];    // 0=dir 1=file

            sprintf(file->Number, "%d", f+1);
            Strncpy(file->Name, (char *)&c[2], MAX_MAC_PATH);
            file->Name[MAX_MAC_PATH] = '\0';

            file->Size = Toolbox_ParseEntrySize(c);
            file++;
         }
         file->Type = -1;  // EOF
      }
   }
#endif
   return files;
}

/* Select a CD image */
void Toolbox_Set_Next_CD(UBYTE index)
{
   UBYTE command[] = {BLUESCSI_TOOLBOX_SET_NEXT_CD, 0, 0, 0, 0, 0, 0, 0, 0, 0};
   int err;
   command[1] = (UBYTE) index;
   if ((err = DoScsiCmd((UBYTE *)scsi_data, MAX_DATA_LEN,
                        (UBYTE *)&command, sizeof(command),
                        (SCSIF_READ | SCSIF_AUTOSENSE))) != 0)
   {
      UBYTE errmsg[80];
      sprintf(errmsg, "SCSI error %d\n", err);
      MessageBox("Toolbox_Set_Next_CD", errmsg);
   }
}

/* Download a file from the SD card */
unsigned long long Toolbox_Download(char *source, char *destination, void (*callback)(int))
{
   unsigned long long result = 0;
   if (files)
   {
      struct FileEntry *file = files;
      unsigned long long count = 0;
      int index = -1;
      int i;
      for (i = 0; i < filecount; i++)
      {
         if (Stricmp(file->Name, source) == 0)
         {
            index = file->Index;
            break;
         }
         file++;
      }

      if (index >= 0)
      {
         int offset = 0; // offset in 4096 size pages
         unsigned long long size = file->Size;
         BPTR fh;
         UBYTE command[] = {BLUESCSI_TOOLBOX_GET_FILE, 0, 0, 0, 0, 0, 0, 0, 0, 0};
         command[1] = index;

         fh = Open(destination, MODE_NEWFILE);
         if (!fh)
         {
            SetIoErr(ERROR_OBJECT_NOT_FOUND);
            PrintFault(IoErr(), destination);
            return 0;
         }

         while (count < size)
         {
            int err;
            command[2] = (offset & 0xFF000000) >> 24;
            command[3] = (offset & 0x00FF0000) >> 16;
            command[4] = (offset & 0x0000FF00) >> 8;
            command[5] = (offset & 0x000000FF);

            if ((err = DoScsiCmd((UBYTE *)scsi_data, MAX_DATA_LEN,
                                 (UBYTE *)&command, sizeof(command),
                                 (SCSIF_READ | SCSIF_AUTOSENSE))) != 0)
            {
               MessageBox("Toolbox_Download", "SCSI error");
               break;
            }

#ifdef TESTMODE
            {
               unsigned long long remaining = size - count;
               unsigned long long chunk = remaining > 4096 ? 4096 : remaining;

               count += chunk;
               offset++;
            }
#else
            if (scsi_cmd->scsi_Actual)
            {
               unsigned long long remaining = size - count;
               ULONG chunk = scsi_cmd->scsi_Actual;

               if ((unsigned long long)chunk > remaining)
               {
                  chunk = (ULONG)remaining;
               }

               if (chunk == 0)
               {
                  break;
               }

               count += chunk;
               offset++;
               Write(fh, scsi_data, chunk);
            }
            else
            {
               break;
            }
#endif

            if (callback && (count == size || (offset % 16 == 0)))
            {
               // Update progress every 64k
               int pc = size ? (int)((count * 100ULL) / size) : 100;
               if (pc > 100)
               {
                  pc = 100;
               }
               callback(pc);
            }
         }
         Close(fh);
         if (callback && count == size)
         {
            callback(100);
         }
         result = count;
      }
      else
      {
         result = -1;
      }
   }
   
   return result;
}

bos4711-adftools-adfextract-c.text:
/* adfextract.c - Copy/extract files from adf-images
 *
 * adftools - A complete package for maintaining image-files for the best
 * Amiga-emulator out there: UAE - http://www.freiburg.linux.de/~uae/
 *
 * Copyright (C)2002-2015 Rikard Bosnjakovic <bos@hack.org>
 */
#include <adflib.h>
#include <errno.h>
#include <fcntl.h>
#include <getopt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>
#include <utime.h>

#include "error.h"
#include "misc.h"
#include "version.h"

/* the name of this program */
char *program_name = ADFEXTRACT;

/* long options that have no short eqvivalent short option */
enum {
  EXTRACT_OPTION = 1
};

/* options */
static struct option long_options[] =
{
  {"extract",	required_argument,	0, EXTRACT_OPTION},
  {"list",	no_argument,		0, 'l'},
  {"tree",	no_argument,		0, 'r'},
  {"help",	no_argument,		0, 'h'},
  {"version",	no_argument,		0, 'V'},

  /* end of options */
  {NULL, 0, NULL, 0}
};

/* struct array for timestamps */
#define MAX_FTS 8

struct fts {
  char   *filename;
  struct utimbuf utime_buf;
};

struct fts *file_timestamps;
static int n_fts = 0;
static int max_fts = MAX_FTS;

/********************************************************************/
/*                        disk file-functions                       */
/********************************************************************/
/* save the timestamp from the adf-file for later update */
void
update_timestamp(char *filename, struct Entry *entry)
{
  struct tm time_str;
  struct utimbuf *utime_buf;
  time_t time_ret;

  if (n_fts == max_fts) {
    /* array is full, increase it */
    max_fts += MAX_FTS;
    file_timestamps = realloc (file_timestamps, sizeof (struct fts) * max_fts);
  }

  utime_buf = &file_timestamps[n_fts].utime_buf;

  time_str.tm_year = entry->year - 1900;
  time_str.tm_mon = entry->month - 1;
  time_str.tm_mday = entry->days;
  time_str.tm_hour = entry->hour;
  time_str.tm_min = entry->mins;
  time_str.tm_sec = entry->secs;
  time_str.tm_isdst = -1;

  time_ret = mktime(&time_str);
  if (time_ret == -1)
    error (0, "cannot set timestamp for %s", filename);
  else {
    utime_buf->actime = time_ret;
    utime_buf->modtime = time_ret;
    file_timestamps[n_fts].filename = strdup (filename);
/*     strcpy(file_timestamps[n_fts].filename, filename); */
    n_fts++;
  }
}
void
do_extract_file(struct Volume *vol, struct Entry *entry, char* path, unsigned char *extbuf)
{
  char *filename;
  char *name = entry->name;
  FILE *out;
  long n_bytes;
  struct File *file;

  /* allocate memory for the path, separator, filename and the trailing separator */
  filename = malloc (strlen (path) + 1 + strlen (name) + 1);
  if (!filename) {
    error (0, "%s: %s", name, strerror (errno));
    return;
  }

  /* construct a full pathname for the file to be extracted (to) */
  sprintf (filename, "%s%c%s", path, DIRSEP, name);
  out = fopen (filename, "wb");
  if (!out) {
    error (0, "%s: Can't open file for output: %s", filename, strerror (errno));
    return;
  }

  /* open the file in the image */
  file = adfOpenFile (vol, name, "r");
  if (!file) {
    error (0, "%s: Can't read file from image. Access bits: '%s'", filename, access2str (entry->access));
    fclose (out);
    return;
  }

  /* read the file from the image */
  n_bytes = adfReadFile(file, BUFSIZE, extbuf);
  while (!adfEndOfFile (file)) {
    fwrite (extbuf, sizeof (unsigned char), n_bytes, out);
    n_bytes = adfReadFile (file, BUFSIZE, extbuf);
  }

  /* write any remaining bytes */
  if (n_bytes > 0)
    fwrite (extbuf, sizeof (unsigned char), n_bytes, out);

  /* we're done.  print some extracting info */
  printf ("Extracted file '%s'\n", filename);

  /* save a copy of the timestamp */
  update_timestamp (filename, entry);

  /* close both files */
  adfCloseFile (file);
  fclose (out);

  free (filename);
}

/* the Recursive Extracter(tm) */
void
do_extract_tree (struct Volume *vol, struct List* tree, char *path, unsigned char *extbuf)
{
  struct Entry* entry;
  char *dir;

  while(tree) {
    entry = tree->content;
    if (entry->type == ST_DIR) {
      /* dir */
      dir = malloc (strlen (path) + 1 + strlen (entry->name) + 1);
      if (!dir) {
	error (0, "Can't allocate memory for %s: %s", entry->name, strerror (errno));
	return;
      }

      /* dir to create */
      sprintf (dir, "%s%c%s", path, DIRSEP, entry->name);

      /* show extracting information */
//      printf ("%s%c\n", dir, DIRSEP);

      if (access (dir, F_OK) == -1) {
	/* dir does not exist, let's create it */
	if (mkdir (dir, 0755) == -1) {
	  error (1, "Can't create '%s': %s", dir, strerror (errno));
	} else {
	  notify ("Created dir '%s'.\n", dir);
          update_timestamp (dir, entry);
	}
      }

      if (tree->subdir != NULL) {
	if (adfChangeDir (vol, entry->name) == RC_OK) {
	  if (dir) {
	    do_extract_tree (vol, tree->subdir, dir, extbuf);
	    free (dir);
	  } else
	    do_extract_tree (vol, tree->subdir, entry->name, extbuf);
	  adfParentDir (vol);
	} else {
	  fprintf (stderr, "ExtractTree: dir \"%s/%s\" not found.\n", path,entry->name);
	}
      }
    } else if (entry->type == ST_FILE) {
      /* file */
      do_extract_file (vol, entry, path, extbuf);
    }

    tree = tree->next;
  }
}

/* entry function for the recursive extracter */
void
extract_tree (char *filename, char *path, struct Volume *volume)
{
  struct List *cell, *list;
  unsigned char *buf;

  buf = malloc (BUFSIZE);
  if (!buf) {
    error (0, "Can't allocate memory for extraction of '%s': %s", filename, strerror (errno));
    return;
  }

  print_volume_header (filename, volume);

  if (strlen (path) == 0)
    /* create a directory with the same name as the image, modulo extension */
    path = strip_extension (basename (filename));

  /* make sure the dir to extract to exists, else create it */
  if (access (path, F_OK) == -1) {
    /* dir does not exist, let's create it */
    if (mkdir (path, 0755) == -1) {
      error (1, "Can't create '%s': %s", path, strerror (errno));
    } else {
      notify ("Created extraction dir '%s'.\n", path);
    }
  }

  cell = list = adfGetRDirEnt (volume, volume->curDirPtr, 1);
  do_extract_tree (volume, cell, path, buf);

  putchar ('\n');
  adfFreeDirList (list);
}

/********************************************************************/
/*                     print version, usage, etc                    */
/********************************************************************/
void
print_usage (int status)
{
  if (!status) {
    notify ("Try '%s --help' for more information.\n", program_name);
  } else {
    printf ("Usage: %s [OPTIONS]... FILE(s)...\n", program_name);
    printf ("List/extract files from an adf-image.\n\n");
    printf ("\t-e                   \tcreates a directory and extracts all contents\n");
    printf ("\t                     \tof the image into there (default)\n");
    printf ("\t    --extract=DIR    \tsame as -e, but extracts to DIR instead\n");
    printf ("\t-l, --list           \tlists root directory contents\n");
    printf ("\t-r, --tree           \tlists directory tree contents\n");
    printf ("\t-h, --help           \tdisplay this help and exit\n");
    printf ("\t-V, --version        \tdisplay version information and exit\n");
    printf ("\n");
    print_footer ();
  }

  exit (0);
}

/********************************************************************/
/*                            here we go                            */
/********************************************************************/
int
main (int argc, char *argv[])
{
  char *extract_dir = "";
  int c, i;
  int n_files;
  struct Device *device;
  struct Volume *volume;

  init_adflib();

  /* parse the options */
  while ((c = getopt_long (argc, argv, "ehV", long_options, NULL)) != -1) {
    switch (c) {
      case 0:
	break;

      case EXTRACT_OPTION:
	extract_dir = optarg;
	break;

      case 'e':
	extract_dir = "";
	break;

      case 'h':
	print_usage (1);
	break;

      case 'V':
	print_version ();
	exit (0);

      default:
	print_usage (0);
    }
  }

  n_files = argc - optind;
  if (n_files == 0) {
    error (0, "Nothing to do");
    print_usage (0);
  }

  /* all remaining arguments should be files */
  if (optind < argc) {
    /* initiate the array for timestamps */
    file_timestamps = malloc (sizeof(struct fts) * MAX_FTS);

    while (optind < argc) {
      char *filename = argv[optind++];

      /* lazy way to mount both the device and the volume (if possible) */
      if (!mount_adf (filename, &device, &volume, READ_ONLY))
	continue;

      extract_tree (filename, extract_dir, volume);

      printf ("Updating timestamps...\n");
      for (i = 0; i < n_fts; i++) {
        char *filename = file_timestamps[i].filename;

        utime(filename, &file_timestamps[i].utime_buf);
      }
    }

    if (file_timestamps)
      free (file_timestamps);
  }

  printf ("All Done.\n");

  cleanup_adflib();
  return 1;
}

