{
  struct ExBase *eb = (struct ExBase *)db;
  struct IOStdReq *isr = (struct IOStdReq *)ior;

  switch(ior->io_Command) {
    case CMD_READ:
      D(("CMD_READ\n"));
      isr->io_Actual = Read(eb->eb_Input,
                            isr->io_Data,
